package com.gomgomapps.math.core;
import java.util.*;import org.junit.Test;import static org.junit.Assert.*;
public class SignedIntervalStoriesTest {
 private static Learning.Profile profile(){Learning.Profile p=new Learning.Profile();p.countryCode="GB";p.educationSystem="england-primary-2021-v1";p.grade=6;return p;}
 @Test public void everyPairChecksPublicPositionsAndBlankHelp(){int count=0;Checker c=new Checker();for(String id:List.of(SignedIntervalStories.TEMPERATURE,SignedIntervalStories.HEIGHT))for(int a=-50;a<=50;a++)for(int b=-50;b<=50;b++){
  Question q=SignedIntervalStories.make(id,a,b);q.answers=new String[]{"999"};q.expression="999";int expected=0;for(int n=Math.min(a,b);n<Math.max(a,b);n++)expected++;assertTrue(c.check(q,List.of(),List.of(""+expected)).correct());Checker.Result wrong=c.check(q,List.of(),List.of(""+(expected+1)));assertEquals(Checker.Status.WRONG_ANSWER,wrong.status);assertEquals(0,wrong.index);
  HelpPlan h=HelpPlan.forQuestion(q);assertEquals(6,h.size());assertFalse(h.canTransfer());assertEquals("signed-intervals-v1",q.studyGuide.teachingVersion);assertTrue(h.restore(null,q.id).entries.stream().allMatch(String::isEmpty));int low=Math.min(a,b),high=Math.max(a,b);List<String> entries=List.of(""+low,""+high,""+Math.abs(low),""+Math.abs(high),low<=0&&high>=0?"add":"subtract",""+expected);for(int j=0;j<6;j++)assertTrue(h.step(j).accepts(entries.get(j)));count++;
 }assertEquals(20402,count);}
 @Test public void actualGradeSixKeepsFreshContextsAndPredecessors(){Generator g=new Generator(new Random(190));for(String id:List.of(SignedIntervalStories.TEMPERATURE,SignedIntervalStories.HEIGHT)){List<String> recent=new ArrayList<>();boolean negative=false,cross=false,sameSide=false;for(int i=0;i<150;i++){Question q=g.next(id,recent,false,GlobalCurriculum.limits("england-primary-2021-v1",id,6));assertFalse(recent.contains(q.signature()));recent.add(q.signature());int[] v=SignedIntervalStories.read(q);assertNotNull(v);negative|=Math.min(v[0],v[1])<0;cross|=Math.min(v[0],v[1])<0&&Math.max(v[0],v[1])>0;sameSide|=(v[0]<0&&v[1]<0)||(v[0]>0&&v[1]>0);assertTrue(q.choices.isEmpty());}assertTrue(negative&&cross&&sameSide);}
  Set<String> ids=new HashSet<>();for(Catalog.Skill s:GlobalCurriculum.available(profile()))ids.add(s.id);assertTrue(ids.containsAll(List.of(SignedIntervalStories.TEMPERATURE,SignedIntervalStories.HEIGHT,NegativeCounting.ID,YearFiveNumberStories.TEMPERATURE)));
  Learning.Profile p=profile();for(String id:List.of(SignedIntervalStories.TEMPERATURE,SignedIntervalStories.HEIGHT)){assertTrue(GlobalCurriculum.pack(p).inGrade(id,6));assertFalse(GlobalCurriculum.pack(p).inGrade(id,5));assertFalse(GlobalCurriculum.scope(p).stream().anyMatch(skill->skill.id.equals(id)));}Learning.Profile common=new Learning.Profile();assertFalse(GlobalCurriculum.available(common).stream().anyMatch(skill->SignedIntervalStories.supports(skill.id)));
 }
 @Test public void invalidPromptsAndInputsDoNotBorrowKeys(){Checker c=new Checker();Question q=SignedIntervalStories.make(SignedIntervalStories.TEMPERATURE,-50,50);for(String raw:List.of("","100.0","1/1","abc","1000"))assertEquals(Checker.Status.INPUT_NEEDED,c.check(q,List.of(),List.of(raw)).status);assertEquals(Checker.Status.WRONG_ANSWER,c.check(q,List.of(),List.of("-100")).status);assertTrue(c.check(q,List.of(),List.of("+100")).correct());q.prompt=q.prompt.replace("-50","-51");assertNull(SignedIntervalStories.read(q));assertEquals(Checker.Status.INPUT_NEEDED,c.check(q,List.of(),List.of("100")).status);assertNull(SignedIntervalStories.read(new Question(SignedIntervalStories.HEIGHT,"-1 + 1","2","2")));}
}
